```sql
SELECT T.team_long_name FROM Team AS T JOIN Match AS M ON T.team_api_id = M.home_team_api_id WHERE M.season = '2015/2016' GROUP BY T.team_api_id ORDER BY COUNT(CASE WHEN M.home_team_goal - M.away_team_goal < 0 THEN 1 END) ASC LIMIT 1;
```

